require('dotenv').config();const fs=require('fs'),path=require('path'),bcrypt=require('bcryptjs'),{Pool}=require('pg');const pool=new Pool({connectionString:process.env.DATABASE_URL,ssl:{rejectUnauthorized:false}});(async()=>{const c=await pool.connect();try{await c.query(fs.readFileSync(path.join(__dirname,'schema.sql'),'utf8'));if(process.env.ADMIN_EMAIL&&process.env.ADMIN_PASSWORD){const h=await bcrypt.hash(process.env.ADMIN_PASSWORD,10);await c.query(`INSERT INTO ke_users(full_name,email,password_hash,role) VALUES('Quản trị viên',$1,$2,'admin') ON CONFLICT(email) DO UPDATE SET password_hash=EXCLUDED.password_hash,role='admin'`,[process.env.ADMIN_EMAIL,h])}console.log('CLEAN LMS DATABASE READY')}finally{c.release();await pool.end()}})().catch(e=>{console.error('BOOTSTRAP ERROR',e);process.exit(1)})